(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,f=x=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:0}).format(x),eur=x=>'€'+f(x);function draw(){const units=n('calc-labs')*n('calc-hplc-count'),v=units*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,upfront=units*(n('roi-unit-cost')+n('roi-install')),annual=units*n('roi-support'),gross=v*(n('calc-recovery')/100*n('calc-solvent-cost')+n('calc-waste-reduction')/100*n('calc-disposal-cost')),max=Math.max(upfront+annual,gross,1),W=880,H=350,L=80,R=25,T=40,B=58,plot=H-T-B,y=v=>H-B-v/max*plot;let svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Investment versus benefit. '+[1,2,3].map(t=>'Year '+t+': investment '+eur((t===1?upfront:0)+annual)+', benefit '+eur(gross)).join('; ')+'.">';for(let i=0;i<=4;i++){let val=max*i/4;svg+='<line x1="'+L+'" y1="'+y(val)+'" x2="'+(W-R)+'" y2="'+y(val)+'" stroke="#dce5eb"/><text x="'+(L-10)+'" y="'+(y(val)+4)+'" font-size="12" fill="#526b7b" text-anchor="end">€'+f(val/1000)+'k</text>';}for(let t=1;t<=3;t++){const cx=L+(t-.5)*(W-L-R)/3;for(const[val,color,x]of [[(t===1?upfront:0)+annual,'#f58220',cx-79],[gross,'#16804a',cx+9]]){svg+='<rect x="'+x+'" y="'+y(val)+'" width="70" height="'+(val/max*plot)+'" rx="3" fill="'+color+'"><title>Year '+t+': '+(color==='#f58220'?'investment ':'benefit ')+eur(val)+'</title></rect><text x="'+(x+35)+'" y="'+(y(val)-10)+'" text-anchor="middle" font-size="13" font-weight="700" fill="#073e60">'+eur(val)+'</text>';}svg+='<text x="'+cx+'" y="'+(H-24)+'" text-anchor="middle" font-size="13" fill="#073e60">Year '+t+'</text>';}el('investment-benefit-chart').innerHTML=svg+'</svg>';el('investment-benefit-summary').textContent='Three years: '+eur(upfront+annual*3)+' total investment versus '+eur(gross*3)+' gross benefit = '+eur(gross*3-upfront-annual*3)+' net cash benefit.';}document.addEventListener('resolve-model',draw);el('calc-reset').addEventListener('click',draw);draw();})();